// Inlined into the "Normalize invoice email" Code node. Plain JS: n8n Code nodes can't import files.
// One shape for both entry points: the local webhook ({ invoice: {...pdf_base64} }) and the live Gmail Trigger.

function domainOf(address) {
  const m = String(address ?? '').toLowerCase().match(/@([a-z0-9.-]+)/);
  return m ? m[1].replace(/>$/, '') : '';
}

function normalizeInvoiceEmail(raw, source) {
  const r = raw ?? {};
  const from = String(r.from?.value?.[0]?.address ?? r.from?.text ?? r.from ?? '').trim();
  return {
    invoice_id: String(r.id ?? r.invoice_id ?? r.messageId ?? '').slice(0, 80),
    from,
    sender_domain: domainOf(from),
    subject: String(r.subject ?? '').slice(0, 300),
    received_at: String(r.received_at ?? r.date ?? ''),
    filename: String(r.filename ?? 'invoice.pdf').replace(/[^A-Za-z0-9._-]/g, '_').slice(0, 120),
    source,
  };
}

// ---- n8n wrapper: one invoice per execution (each needs its own approval wait) ----
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i]; const j = item.json;
  let raw; let source; let b64 = '';
  if (j.body && j.body.invoice) { source = 'webhook'; raw = j.body.invoice; b64 = String(raw.pdf_base64 ?? ''); }
  else {
    source = 'gmail'; raw = j;
    const key = Object.keys(item.binary ?? {}).find((k) => String(item.binary[k].mimeType ?? '').includes('pdf'));
    if (key) { b64 = (await this.helpers.getBinaryDataBuffer(i, key)).toString('base64'); raw = { ...j, filename: item.binary[key].fileName }; }
  }
  if (!b64) throw new Error('No PDF attachment on this email. Nothing to process.');
  out.push({ json: { ...normalizeInvoiceEmail(raw, source), pdf_base64: b64 } });
}
return out.slice(0, 1);

// Keep the PDF text, drop the base64 so later nodes stay small.
const meta = $('Normalize invoice email').first().json;
const text = String($input.first().json.text ?? '');
const { pdf_base64, ...rest } = meta;
return [{ json: { ...rest, pdf_text: text.slice(0, 20000), pdf_chars: text.length } }];

